from pathlib import Path
p=Path(__file__).resolve().parents[1];src=p/'04_研发源码/app/r4'
js=r'''// Daily continuity: explicit rules, actual sessions and browser-local progress.
state.wellness.continuity={checkpoint:null,...(state.wellness.continuity||{})};
state.journeyType='all';
function journeyLatest(){return [...state.wellness.sessions].reverse().find(s=>practices[s.practice]&&s.seconds>0);}
function journeyRecommendation(){const entry=body4Entry(),evaluation=entry?body4Evaluation(entry):null,last=journeyLatest();let key=(evaluation?.keys||[]).find(k=>practices[k])||'breath',reason=evaluation?.basis||t('Begin with one comfortable minute.','先给自己一个舒适的小停顿。');if(last?.feeling==='notfit'){key=last.practice==='ground'?'breath':'ground';reason=t('You said the last approach did not suit you. Try a different short practice.','你觉得上次的方式不适合，今天换一种短体验。');}else if(last?.feeling==='same'&&last.seconds>=120){key='breath';reason=t('You felt about the same last time. Begin with a shorter practice today.','上次感觉差不多，今天先试一段更短的练习。');}else if(last?.feeling==='lighter'){key=last.practice;reason=t('You reported more ease last time. Return to that practice if it feels useful.','你上次反馈舒展了一点，可以再试试这段练习。');}return {key,reason,evaluation,last};}
function journeyAction(){const c=state.wellness.continuity.checkpoint;if(c&&c.date===today()&&practices[c.practice]&&c.seconds>0)return {key:c.practice,resume:true,label:c.seconds>=practices[c.practice].seconds?t('Reflect on last practice','回顾上次练习'):t('Continue last practice','继续上次练习'),reason:t('Actual progress saved: ','已保留实际进度：')+formatTime(c.seconds)};const r=journeyRecommendation();return {...r,resume:false,label:r.last?t('Your next small practice','今天，再留一个片刻'):t('Begin a short practice','从一次短体验开始')};}
function journeyCheckpoint(){if(state.page!=='player'||!practices[state.practiceKey]||state.audioSeconds<1)return;state.wellness.continuity.checkpoint={practice:state.practiceKey,seconds:Math.min(state.audioSeconds,practices[state.practiceKey].seconds),date:today()};persist();}
const journeyOpenBefore=openPractice;openPractice=function(key,slot){state.wellness.continuity.checkpoint=null;journeyOpenBefore(key,slot);};
const journeySaveBefore=savePractice;savePractice=function(){if(state.audioSeconds>=1){state.wellness.continuity.checkpoint=null;persist();}journeySaveBefore();};
function journeyStart(key,resume=false){const checkpoint=resume?state.wellness.continuity.checkpoint:null;openPractice(practices[key]?key:'breath');if(checkpoint&&checkpoint.practice===key&&checkpoint.date===today()){state.audioSeconds=Math.min(checkpoint.seconds,practices[key].seconds);state.playerEnded=state.audioSeconds>=practices[key].seconds;state.wellness.continuity.checkpoint=checkpoint;render(false);}if(!state.playerEnded)startAudio();}
function journeySaveFeeling(value){if(!['lighter','same','rest','notfit'].includes(value)||!state.lastSession)return;const session=state.wellness.sessions.find(s=>s.id===state.lastSession.id);if(session)session.feeling=value;state.lastSession.feeling=value;persist();render(false);}
function journeyAdvice(r,compact=false){return `<section class="j-recommend ${compact?'is-compact':''}"><span class="j-label">${t('A PRACTICE FOR THIS MOMENT','适合此刻的一小步')}</span><h2>${practiceName(r.key)}</h2><p class="j-reason">${esc(r.reason)}</p><button class="btn full" data-action="journey-start" data-practice="${r.key}">${t('Begin this practice','开始这段练习')}${icon('arrow')}</button><button class="j-alternative" data-action="journey-alternative">${t('Choose another approach','也可以换一种方式')}</button></section>`;}
function journeyAssessment(){const entry=body4Entry(),r=journeyRecommendation();return `<section class="page j-assessment">${pxTop(t('Body check-in','身心自评'),t('Four questions about your own experience','四个问题，留意自己的感受'),'body')}<form id="px-body-form" class="px-quick-form j-checkin-form">${body4Fields().map(([key,label],i)=>`<label><span class="j-question-number">0${i+1}</span><span>${label}</span><select class="input" name="${key}" required><option value="">${t('Choose','请选择')}</option>${answerChoices()[key].map(([v,n])=>`<option value="${v}" ${entry?.[key]===v?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<button class="btn" type="submit">${entry?t('Update and see my next step','更新感受，看看下一步'):t('Save and find a starting point','记下此刻，找到起点')}</button></form>${entry?`<section class="j-state-summary"><span class="j-label">${t('YOUR OWN CHECK-IN','依据你的主动回答')}</span><h2>${esc(r.evaluation.title)}</h2><p>${esc(r.evaluation.copy)}</p></section>${journeyAdvice(r)}`:''}<p class="px-note">${t('These rules use your own answers, not device measurements or a medical diagnosis.','建议依据自述与练习反馈，不是设备测量或医疗判断。')}</p>${pxDeviceRow('body')}</section>`;}
function journeyBody(){const r=journeyRecommendation(),entry=body4Entry();return `<section class="page px-map-page j-body" data-map="body">${pxTop(t('Body map','身体地图'),t('Notice first, then choose a small action','先觉察，再选择一个小行动'))}<div class="px-map-hero j-body-intro"><span class="px-kicker">${entry?t('TODAY’S CHECK-IN','今天的自述已记录'):t('START WITH HOW YOU FEEL','从此刻的感受开始')}</span><h2>${entry?esc(r.evaluation.title):t('How are you feeling today?','今天，身体感觉如何？')}</h2><p>${entry?esc(r.evaluation.basis):t('Sleep, energy, stress and comfort. No measuring device is needed.','睡眠、精力、压力、舒适度，从四个回答开始。')}</p></div><div class="j-body-action">${entry?`<button class="btn full" data-action="journey-start" data-practice="${r.key}">${t('Try ','先试试：')}${practiceName(r.key)}</button><p class="j-reason">${esc(r.reason)}</p>`:go(t('Begin my check-in','开始身心自评'),'bodyAssessment','full')}</div><div class="px-grid">${pxTile('activity',t('Body check-in','身心自评'),entry?t('Update today','更新今天的感受'):t('Four questions','四个问题，了解此刻'),'bodyAssessment')}${pxTile('leaf',t('Daoyin','中医导引'),t('Gentle movement','温和活动，舒展身体'),'bodyCulture')}${pxTile('moon',t('Sleep & stress','睡眠与压力'),t('Choose a quiet practice','选择合适的放松练习'),'bodyRecovery')}${pxTile('headphones',t('Soundscapes','放松音景'),t('A moment with sound','让声音陪你片刻'),'music')}</div><div class="ew-map-flow" aria-label="${t('Reflect, practice and revisit','觉察、实践与回看')}">${[[t('Reflect','觉察当下'),'bodyAssessment'],[t('Practice','开始实践'),'bodyRecovery'],[t('Revisit','回看记录'),'bodyHistory']].map(([label,to],i)=>`<button data-action="go" data-to="${to}"><span>0${i+1}</span>${label}${icon('arrow')}</button>`).join('')}</div>${pxDeviceRow('body')}${go(t('Growth records','成长记录'),'growth','link')}</section>`;}
function journeySessionDone(){const s=state.lastSession;if(!s)return showGrowth();const next=journeyRecommendation();return `<section class="page j-session-done">${pxTop(t('A moment, kept','留住这一刻'),'','home')}<div class="j-completion"><span class="j-label">${s.complete?t('PRACTICE COMPLETED','完整体验已记录'):t('A REAL SMALL PAUSE','这一小段，也值得留下')}</span><h1>${t('How do you feel now?','现在，感觉怎么样？')}</h1><p>${practiceName(s.practice)} · ${formatTime(s.seconds)} ${t('actually practised','实际练习')}</p></div><div class="j-feedback" aria-label="${t('My own feedback','我的练后感受')}">${[['lighter',t('A little more ease','舒展了一点')],['same',t('About the same','感觉差不多')],['notfit',t('Not for me','这种方式不适合我')]].map(([v,label])=>`<button data-action="session-feeling" data-value="${v}" aria-pressed="${s.feeling===v}">${label}${s.feeling===v?icon('check'):icon('arrow')}</button>`).join('')}</div>${s.feeling?`<div class="j-next-step"><span class="j-label">${t('FOR NEXT TIME','下一次，可以这样开始')}</span><h2>${practiceName(next.key)}</h2><p>${esc(next.reason)}</p>${go(t('Return to today','回到首页'),'home','full')}</div>`:`<p class="px-note">${t('Optional feedback helps choose a next step. There is no correct answer.','反馈是自愿的，会用于选择下次的小练习，没有标准答案。')}</p>${go(t('Return for now','先回到首页'),'home','secondary full')}`}${go(t('Revisit my actual records','回看我的实际记录'),'growth','link')}</section>`;}
function journeyGrowth(){const all=growthEvents(),limit=state.growthRange==='all'?null:shiftedDate(1-Number(state.growthRange)),period=all.filter(e=>(!limit||e.date>=limit)&&e.date<=today()),filtered=period.filter(e=>state.journeyType==='all'||(state.journeyType==='practice'?['session','music'].includes(e.kind):state.journeyType==='reflection'?['life','body','mind'].includes(e.kind):e.kind===state.journeyType)),sessions=state.wellness.sessions.filter(s=>(!limit||s.date>=limit)&&s.date<=today()&&s.seconds>0),music=(state.daily.musicSessions||[]).filter(s=>(!limit||s.date>=limit)&&s.date<=today()),practiceSeconds=sessions.reduce((n,s)=>n+Number(s.seconds||0),0),musicSeconds=music.reduce((n,s)=>n+Number(s.seconds||0),0),ease=sessions.filter(s=>s.feeling==='lighter').length;const days=[...new Set(filtered.map(e=>e.date))];return `<section class="page daily-page j-growth">${ewMainHeader(t('Growth records','成长记录'),t('A LOOK BACK AT YOUR DAYS','回看真实发生的日常'))}<div class="daily-filter">${[['7',t('7 days','近7天')],['30',t('30 days','近30天')],['all',t('All','全部')]].map(([id,label])=>`<button data-action="growth-filter" data-range="${id}" aria-pressed="${state.growthRange===id}">${label}</button>`).join('')}</div><section class="j-review"><span class="j-label">${t('YOUR ACTUAL RECORDS','这段时间，你留下了')}</span><div class="j-review-values"><div><strong>${sessions.length}</strong><span>${t('Practices','次实际练习')}</span></div><div><strong>${formatTime(practiceSeconds)}</strong><span>${t('Time in practice','实际练习时长')}</span></div><div><strong>${formatTime(musicSeconds)}</strong><span>${t('Listening time','实际聆听时长')}</span></div></div><p>${sessions.length?t('You kept ','你留下了 ')+sessions.length+t(' real practices. ',' 次实际练习。')+(ease?t('On ','其中 ')+ease+t(' occasions, you reported more ease.',' 次反馈是“舒展了一点”。'):t('Feedback will appear here when you choose to leave it.','自愿留下感受后，可以在这里一起回看。')):t('Your first real practice can begin today.','可以从今天的一小段真实体验开始。')}</p></section><div class="j-record-types" aria-label="${t('Record types','记录类型')}">${[['all',t('All','全部')],['practice',t('Practice & sound','练习与聆听')],['reflection',t('Reflections','感受与觉察')],['checkin',t('Check-ins','签到')],['card',t('Cards','卡片')]].map(([id,label])=>`<button data-action="journey-filter" data-type="${id}" aria-pressed="${state.journeyType===id}">${label}</button>`).join('')}</div>${filtered.length?`<div class="daily-growth-list">${days.map(day=>`<section class="daily-growth-day"><h4>${dateLabel(day)}</h4>${filtered.filter(e=>e.date===day).map(e=>{const session=e.kind==='session'?sessions.find(s=>s.id===e.id):null;return `<button class="daily-growth-entry" data-action="growth-view" data-kind="${e.kind}" data-date="${e.date}" ${e.id?`data-id="${e.id}"`:''}><span class="path-icon">${icon(e.symbol)}</span><span><b>${e.title}</b><small>${esc(e.copy)}${session?.feeling?' · '+esc(session.feeling==='notfit'?t('Not for me','这种方式不适合我'):feelingLabel(session.feeling)):''}</small></span>${icon('arrow')}</button>`;}).join('')}</section>`).join('')}</div>`:`<div class="j-record-empty"><h2>${t('No matching records yet','这段时间还没有这类记录')}</h2><p>${t('Change a filter or begin a small practice.','可以换个时间或类型，也可以留下一次真实体验。')}</p><button class="btn secondary full" data-action="journey-start" data-practice="breath">${t('Begin one minute','从一分钟开始')}</button></div>`}<p class="px-note">${t('Only actual practice and listening are counted here. App-open time is a separate ledger. Records remain local to this browser.','这里仅统计实际练习和聆听，全局APP计时独立记录。个人档案仍保存在当前浏览器，暂不完整跨设备同步。')}</p></section>`;}
Object.assign(screens,{body:journeyBody,bodyAssessment:journeyAssessment,sessionDone:journeySessionDone,growth:journeyGrowth});
function journeyMount(){const cta=document.querySelector('.xl-practice-entry'),label=document.querySelector('.xl-scene-label');if(state.page==='home'&&cta){const a=journeyAction();cta.dataset.action='journey-home';delete cta.dataset.to;cta.innerHTML=esc(a.label)+icon('arrow');cta.setAttribute('aria-label',a.label+' · '+a.reason);if(label)label.textContent=a.reason;}if(state.page==='player'){const phase=document.querySelector('.breath-circle .phase');if(phase&&!state.audioPlaying)phase.textContent=state.playerEnded?t('A moment to reflect','结束后，留意一下感受'):state.audioSeconds>0?t('Paused, return when ready','已暂停，准备好再继续'):t('A gentle beginning','轻轻开始');}}
const journeyRenderBefore=renderNow;renderNow=function(resetScroll=true){journeyRenderBefore(resetScroll);journeyMount();};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||!el.dataset.action.startsWith('journey-'))return;e.preventDefault();e.stopImmediatePropagation();const a=el.dataset.action;if(a==='journey-home'){const next=journeyAction();journeyStart(next.key,next.resume);}else if(a==='journey-start')journeyStart(el.dataset.practice);else if(a==='journey-filter'){state.journeyType=el.dataset.type;render(false);}else if(a==='journey-alternative')sheet(t('Choose what suits you','选择适合此刻的方式'),`<p class="small">${t('These are optional daily practices. You can stop at any time.','这些是可自由选择的日常练习，随时可以停止。')}</p><div class="j-other-practices">${['breath','ground','scan','sleep'].map(k=>`<button data-action="journey-choice" data-practice="${k}"><span>${practiceName(k)}</span>${icon('arrow')}</button>`).join('')}</div>`);else if(a==='journey-choice'){closeSheet();journeyStart(el.dataset.practice);}},true);
setInterval(()=>{if(state.page==='player'&&state.audioSeconds>=1)journeyCheckpoint();},1000);
window.addEventListener('pagehide',journeyCheckpoint);
render(false);
'''
(src/'journey.js').write_text(js,encoding='utf-8')
css=r'''/* A task-led continuity layer inside the chosen Xuanliu design. */
body[data-theme=xuanliu] .xl-practice-entry{background:var(--cta);color:var(--on-cta);border-color:var(--cta);font-size:11px;min-height:43px;padding:10px 12px;font-weight:550;max-width:49%}body[data-theme=xuanliu] .xl-scene-label{font:10px/1.65 var(--sans);letter-spacing:0;max-width:46%;bottom:20px;white-space:normal}body[data-theme=xuanliu] .quote-banner-text{font-size:27px}.j-label{display:block;font:9px/1.7 var(--sans);letter-spacing:.09em;color:var(--muted)}.j-checkin-form{gap:0!important}.j-checkin-form>label{display:grid!important;grid-template-columns:24px minmax(0,1fr) minmax(112px,.9fr);gap:8px;align-items:center;padding:14px 0;border-bottom:1px solid var(--line);font-size:13px}.j-question-number{font:11px Consolas;color:var(--cta)}.j-checkin-form select{margin:0;padding:11px 9px;font-size:12px;border-radius:6px}.j-checkin-form>.btn{margin-top:19px;font-size:13px}.j-state-summary{padding:23px 0 18px;border-bottom:1px solid var(--line)}.j-state-summary h2{font:400 24px/1.6 var(--serif);margin:9px 0}.j-state-summary p,.j-reason{font-size:11px;line-height:1.85;color:var(--muted)}.j-recommend{padding:23px 0;border-bottom:1px solid var(--line)}.j-recommend h2{font:400 23px/1.6 var(--serif);margin:9px 0}.j-recommend>.btn{margin-top:16px;font-size:13px}.j-alternative{border:0;background:none;color:var(--muted);font-size:11px;padding:13px 0;margin-top:4px}.j-other-practices{display:grid;gap:10px;margin-top:16px}.j-other-practices button{border:1px solid var(--line);background:var(--card);border-radius:6px;color:var(--ink);display:flex;justify-content:space-between;gap:10px;padding:16px;font-size:13px}.j-other-practices .icon{width:15px;height:15px}body[data-theme=xuanliu] .j-body .j-body-intro{min-height:132px;margin:7px 0 12px;padding:14px 0 28px}body[data-theme=xuanliu] .j-body-intro h2{font-size:23px;line-height:1.5;margin:8px 0}body[data-theme=xuanliu] .j-body-intro>p{font-size:10px;line-height:1.7;max-width:97%}.j-body-action{margin-bottom:15px}.j-body-action .btn{font-size:12px;min-height:44px}.j-body-action .j-reason{margin-top:8px;font-size:10px}body[data-theme=xuanliu] .j-body .px-grid{gap:8px}body[data-theme=xuanliu] .j-body .px-tile{min-height:93px;padding:14px}.j-completion{padding:22px 0 27px;border-bottom:1px solid var(--line)}.j-completion h1{font:400 29px/1.5 var(--serif);margin:12px 0}.j-completion p{font-size:12px;color:var(--muted)}.j-feedback{display:grid;gap:10px;margin:25px 0}.j-feedback button{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:55px;background:var(--card);color:var(--ink);border:1px solid var(--line);border-radius:7px;padding:15px;font-size:13px}.j-feedback [aria-pressed=true]{border-color:var(--cta);background:var(--soft);color:var(--cta)}.j-feedback .icon{width:17px;height:17px}.j-next-step{padding:20px 0}.j-next-step h2{font:400 23px/1.5 var(--serif);margin:9px 0}.j-next-step p{font-size:12px;line-height:1.9;color:var(--muted);margin:0 0 19px}.j-review{padding:21px 0;border-bottom:1px solid var(--line)}.j-review-values{display:grid;grid-template-columns:.8fr 1.1fr 1.1fr;gap:10px;margin:13px 0 15px}.j-review-values>div{min-width:0}.j-review-values strong{font:400 25px/1.5 Georgia,serif;display:block;color:var(--ink)}.j-review-values span{font-size:9px;color:var(--muted)}.j-review>p{font-size:11px;line-height:1.9;color:var(--muted)}.j-record-types{display:flex;flex-wrap:wrap;gap:6px;padding:18px 0}.j-record-types button{font-size:10px;min-height:36px;padding:9px;background:transparent;border:1px solid var(--line);border-radius:5px;color:var(--muted)}.j-record-types [aria-pressed=true]{border-color:var(--cta);background:var(--soft);color:var(--cta)}.j-growth .daily-growth-entry{background:none;border-radius:0;border:0;border-bottom:1px solid var(--line);padding:17px 0}.j-growth .daily-growth-entry b{font-size:13px}.j-growth .daily-growth-entry small{font-size:10px;line-height:1.8}.j-growth .daily-growth-day h4{font-size:16px}.j-record-empty{padding:25px 0}.j-record-empty h2{font:400 23px/1.6 var(--serif)}.j-record-empty p{font-size:12px;color:var(--muted);margin:10px 0 18px}@media(max-height:780px){body[data-theme=xuanliu] .quote-banner-text{font-size:24px}body[data-theme=xuanliu] .xl-practice-entry{font-size:10px;padding:9px;min-height:40px}body[data-theme=xuanliu] .xl-scene-label{font-size:9px}body[data-theme=xuanliu] .j-body .j-body-intro{min-height:110px;padding-bottom:15px}body[data-theme=xuanliu] .j-body .px-tile{min-height:85px;padding:13px}.j-body-action{margin-bottom:11px}.j-body-action .j-reason{font-size:9px}}
'''
(src/'journey.css').write_text(css,encoding='utf-8')
f=src/'build.py';s=f.read_text(encoding='utf-8').replace("'platform.css','xuanliu.css']","'platform.css','xuanliu.css','journey.css']").replace("'platform.js','xuanliu.js']","'platform.js','xuanliu.js','journey.js']");f.write_text(s,encoding='utf-8')
f=src/'base.js';s=f.read_text(encoding='utf-8').replace("else if(action==='close-player'){stopAudio();", "else if(action==='close-player'){if(typeof journeyCheckpoint==='function')journeyCheckpoint();stopAudio();");f.write_text(s,encoding='utf-8')
f=src/'app.js';s=f.read_text(encoding='utf-8').replace("else if(a==='session-feeling'){if(state.lastSession){state.lastSession.feeling=el.dataset.value;render(false);}}", "else if(a==='session-feeling'){if(typeof journeySaveFeeling==='function')journeySaveFeeling(el.dataset.value);else if(state.lastSession){state.lastSession.feeling=el.dataset.value;render(false);}}")
f.write_text(s,encoding='utf-8');print('Implemented first module: guided body check-in, meaningful next action, real progress return, feedback rules and typed growth review.')
